components.css:
.ds-target-control { padding: 13px 14px 14px; background: var(--panel, #151922); color: var(--text, #f2f5f7); font-family: "Mona Sans", "Helvetica Neue", sans-serif; }
.ds-control-label { display: block; margin-bottom: 10px; color: var(--dim, #7e8997); font: 700 10px/1.2 ui-monospace, SFMono-Regular, Menlo, monospace; letter-spacing: .08em; text-transform: uppercase; }
.ds-target-row { display: flex; }
.ds-target-button { min-width: 92px; padding: 9px 16px; border: 1px solid var(--line, #303744); border-right-width: 0; border-radius: 0; background: transparent; color: var(--muted, #aab3bf); cursor: pointer; font: 700 14px/1.2 "Mona Sans", "Helvetica Neue", sans-serif; }
.ds-target-button:last-child { border-right-width: 1px; }
.ds-target-button:hover { background: var(--panel-strong, #1b202a); color: var(--text, #f2f5f7); }
.ds-target-button:focus-visible { position: relative; z-index: 1; outline: 3px solid var(--focus, #8cc8ff); outline-offset: 3px; }
.ds-target-button:active { background: #282f3b; }
.ds-target-button-active, .ds-target-button-active:hover, .ds-target-button-active:active { border-color: #e9eff5; background: #e9eff5; color: #101318; }

.ds-search-field { display: block; padding: 13px 16px 14px; background: var(--panel, #151922); color: var(--text, #f2f5f7); font-family: "Mona Sans", "Helvetica Neue", sans-serif; }
.ds-search-label { display: block; margin-bottom: 10px; color: var(--dim, #7e8997); font: 700 10px/1.2 ui-monospace, SFMono-Regular, Menlo, monospace; letter-spacing: .08em; text-transform: uppercase; }
.ds-search-input { width: 100%; height: 38px; border: 0; border-bottom: 1px solid var(--line-bright, #4a5565); border-radius: 0; outline: 0; background: transparent; color: var(--text, #f2f5f7); font: 400 16px/1.2 "Mona Sans", "Helvetica Neue", sans-serif; }
.ds-search-input::placeholder { color: var(--dim, #7e8997); }
.ds-search-input:hover { border-bottom-color: var(--muted, #aab3bf); }
.ds-search-input:focus-visible { outline: 3px solid var(--focus, #8cc8ff); outline-offset: 3px; }

.ds-theme-card { min-width: 0; overflow: clip; contain: layout paint; border: 1px solid var(--ds-card-border); border-radius: 14px; background: var(--ds-card-bg); color: var(--ds-card-fg); font-family: "Mona Sans", "Helvetica Neue", sans-serif; }
.ds-theme-card-button { display: block; width: 100%; min-height: 286px; padding: 18px; border: 0; background: transparent; color: inherit; cursor: pointer; text-align: left; }
.ds-theme-card-button:focus-visible { outline: 3px solid var(--ds-card-ring); outline-offset: -4px; }
.ds-theme-heading { display: flex; min-height: 52px; align-items: flex-start; justify-content: space-between; gap: 12px; }
.ds-theme-name { display: block; font-size: 17px; line-height: 1.2; letter-spacing: -.02em; }
.ds-theme-meta { display: block; margin-top: 7px; color: var(--ds-card-muted); font: 700 10px/1.2 ui-monospace, SFMono-Regular, Menlo, monospace; letter-spacing: .06em; text-transform: uppercase; }
.ds-contrast-badge { flex: none; padding: 5px 7px; border: 1px solid var(--ds-card-border); color: var(--ds-card-muted); font: 700 9px/1.2 ui-monospace, SFMono-Regular, Menlo, monospace; }
.ds-interface-specimen { display: grid; grid-template-columns: 42px 1fr; min-height: 132px; margin-top: 16px; overflow: hidden; border: 1px solid var(--ds-card-border); border-radius: 10px; background: var(--ds-card-raised); transition: background-color 180ms ease-out, border-color 180ms ease-out, transform 180ms ease-out; }
.ds-theme-card-button:hover .ds-interface-specimen, .ds-theme-card-button:focus-visible .ds-interface-specimen { transform: translateY(-2px); }
.ds-theme-card-button:active .ds-interface-specimen { transform: translateY(0); }
.ds-specimen-rail { border-right: 1px solid var(--ds-card-border); background: var(--ds-card-control); }
.ds-specimen-main { padding: 17px 15px; }
.ds-specimen-title, .ds-specimen-copy { display: block; border-radius: 2px; }
.ds-specimen-title { width: 52%; height: 8px; background: var(--ds-card-fg); }
.ds-specimen-copy { width: 78%; height: 6px; margin-top: 11px; background: var(--ds-card-muted); }
.ds-specimen-command { display: grid; gap: 6px; margin-top: 20px; padding: 11px; background: var(--ds-card-control); }
.ds-specimen-command i { display: block; height: 4px; background: var(--ds-card-muted); opacity: .78; }
.ds-specimen-command i:nth-child(1) { width: 82%; }
.ds-specimen-command i:nth-child(2) { width: 64%; }
.ds-specimen-command i:nth-child(3) { width: 72%; background: var(--ds-card-accent); opacity: 1; }
.ds-palette-strip { display: grid; grid-template-columns: repeat(8, 1fr); height: 24px; margin-top: 16px; overflow: hidden; border-radius: 6px; }
.ds-palette-strip i { min-width: 0; }
@media (prefers-reduced-motion: reduce) { .ds-interface-specimen { transition-duration: .01ms; } }

.ds-selection-tray { display: flex; width: min(920px, calc(100% - 28px)); margin: 0 auto; padding: 18px 20px; align-items: center; justify-content: space-between; gap: 30px; border: 1px solid var(--line-bright, #4a5565); border-radius: 14px; background: #171c24; color: var(--text, #f2f5f7); box-shadow: 0 18px 48px rgba(0,0,0,.42); font-family: "Mona Sans", "Helvetica Neue", sans-serif; }
.ds-selection-target { margin: 0 0 5px; color: var(--focus, #8cc8ff); font: 400 11px/1.2 ui-monospace, SFMono-Regular, Menlo, monospace; text-transform: uppercase; }
.ds-selection-title { margin: 0; font-size: 22px; line-height: 1.2; }
.ds-selection-description { margin: 6px 0 0; color: var(--muted, #aab3bf); font-size: 13px; }
.ds-selection-actions { display: flex; flex: none; gap: 10px; }
.ds-tray-action { display: inline-flex; min-height: 42px; padding: 0 15px; align-items: center; justify-content: center; border: 1px solid #dce7f1; border-radius: 8px; background: #eaf1f7; color: #101318; cursor: pointer; font: 750 14px/1.2 "Mona Sans", "Helvetica Neue", sans-serif; text-decoration: none; }
.ds-tray-action:hover { background: #fff; }
.ds-tray-action:focus-visible { outline: 3px solid var(--focus, #8cc8ff); outline-offset: 3px; }
.ds-tray-action:active { background: #dce7f1; }
@media (max-width: 590px) { .ds-selection-tray { display: block; width: auto; padding: 14px; } .ds-selection-description { display: none; } .ds-selection-title { font-size: 19px; } .ds-selection-actions { margin-top: 12px; } .ds-tray-action { flex: 1; } }

.ds-primary-action { display: inline-flex; min-height: 42px; padding: 0 15px; align-items: center; justify-content: center; border: 1px solid #dce7f1; border-radius: 8px; background: #eaf1f7; color: #101318; cursor: pointer; font: 750 14px/1.2 "Mona Sans", "Helvetica Neue", sans-serif; text-decoration: none; }
.ds-primary-action:hover { background: #fff; }
.ds-primary-action:focus-visible { outline: 3px solid var(--focus, #8cc8ff); outline-offset: 3px; }
.ds-primary-action:active { background: #dce7f1; }

.ds-site-header { display: flex; min-height: 64px; padding: 0 28px; align-items: center; justify-content: space-between; border-bottom: 1px solid color-mix(in srgb, var(--line, #303744), transparent 22%); background: color-mix(in srgb, var(--page, #0d1015), transparent 8%); color: var(--text, #f2f5f7); backdrop-filter: blur(14px); font-family: "Mona Sans", "Helvetica Neue", sans-serif; }
.ds-brand { display: inline-flex; gap: 10px; align-items: center; color: inherit; font-weight: 760; letter-spacing: -.02em; text-decoration: none; }
.ds-brand svg { width: 21px; height: 21px; color: #d6e2ef; }
.ds-brand:focus-visible, .ds-header-link:focus-visible { outline: 3px solid var(--focus, #8cc8ff); outline-offset: 3px; }
.ds-header-links { display: flex; gap: 26px; }
.ds-header-link { color: var(--muted, #aab3bf); font-size: 14px; font-weight: 600; text-decoration: none; }
.ds-header-link:hover { color: var(--text, #f2f5f7); }
.ds-header-link:active { color: var(--focus, #8cc8ff); }
@media (max-width: 850px) { .ds-site-header { padding-inline: 16px; } .ds-header-links { gap: 14px; } .ds-header-link { font-size: 12px; } .ds-header-link-themes { display: none; } }
